90	export async function startServer(): Promise<StartedServer> {
91	  let config = loadConfig();
92	  initTelemetry({ enabled: config.telemetryEnabled });
93	  if (process.env.PAPERCLIP_SECRETS_PROVIDER === undefined) {
94	    process.env.PAPERCLIP_SECRETS_PROVIDER = config.secretsProvider;
95	  }
96	  if (process.env.PAPERCLIP_SECRETS_STRICT_MODE === undefined) {
97	    process.env.PAPERCLIP_SECRETS_STRICT_MODE = config.secretsStrictMode ? "true" : "false";
98	  }
99	  if (process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE === undefined) {
100	    process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE = config.secretsMasterKeyFilePath;
101	  }
