191	  function rewriteLocalUrlPort(rawUrl: string | undefined, port: number): string | undefined {
192	    if (!rawUrl) return undefined;
193	    try {
194	      const parsed = new URL(rawUrl);
195	      // The URL API normalizes default ports like :80/:443 to "", so treat them as stable URLs.
196	      if (!parsed.port) return rawUrl;
197	      parsed.port = String(port);
198	      return parsed.toString();
199	    } catch {
200	      return rawUrl;
201	    }
202	  }
203	  
204	  const LOCAL_BOARD_USER_ID = "local-board";
205	  const LOCAL_BOARD_USER_EMAIL = "local@paperclip.local";
206	  const LOCAL_BOARD_USER_NAME = "Board";
207	  
208	  async function ensureLocalTrustedBoardPrincipal(db: any): Promise<void> {
209	    const now = new Date();
210	    const existingUser = await db
211	      .select({ id: authUsers.id })
212	      .from(authUsers)
213	      .where(eq(authUsers.id, LOCAL_BOARD_USER_ID))
214	      .then((rows: Array<{ id: string }>) => rows[0] ?? null);
215	  
216	    if (!existingUser) {
217	      await db.insert(authUsers).values({
218	        id: LOCAL_BOARD_USER_ID,
219	        name: LOCAL_BOARD_USER_NAME,
220	        email: LOCAL_BOARD_USER_EMAIL,
221	        emailVerified: true,
222	        image: null,
223	        createdAt: now,
224	        updatedAt: now,
225	      });
226	    }
227	  
228	    const role = await db
229	      .select({ id: instanceUserRoles.id })
230	      .from(instanceUserRoles)
231	      .where(and(eq(instanceUserRoles.userId, LOCAL_BOARD_USER_ID), eq(instanceUserRoles.role, "instance_admin")))
232	      .then((rows: Array<{ id: string }>) => rows[0] ?? null);
233	    if (!role) {
234	      await db.insert(instanceUserRoles).values({
235	        userId: LOCAL_BOARD_USER_ID,
236	        role: "instance_admin",
237	      });
238	    }
239	  
240	    const companyRows = await db.select({ id: companies.id }).from(companies);
241	    for (const company of companyRows) {
242	      const membership = await db
243	        .select({ id: companyMemberships.id })
244	        .from(companyMemberships)
245	        .where(
246	          and(
247	            eq(companyMemberships.companyId, company.id),
248	            eq(companyMemberships.principalType, "user"),
249	            eq(companyMemberships.principalId, LOCAL_BOARD_USER_ID),
250	          ),
251	        )
252	        .then((rows: Array<{ id: string }>) => rows[0] ?? null);
253	      if (membership) continue;
254	      await db.insert(companyMemberships).values({
255	        companyId: company.id,
256	        principalType: "user",
257	        principalId: LOCAL_BOARD_USER_ID,
258	        status: "active",
259	        membershipRole: "owner",
260	      });
261	    }
262	  }
263	  
264	  let db;
265	  let pluginMigrationDb;
266	  let embeddedPostgres: EmbeddedPostgresInstance | null = null;
267	  let embeddedPostgresStartedByThisProcess = false;
268	  let migrationSummary: MigrationSummary = "skipped";
269	  let activeDatabaseConnectionString: string;
270	  let resolvedEmbeddedPostgresPort: number | null = null;
271	  let startupDbInfo:
272	    | { mode: "external-postgres"; connectionString: string }
273	    | { mode: "embedded-postgres"; dataDir: string; port: number };
274	  if (config.databaseUrl) {
275	    const migrationUrl = config.databaseMigrationUrl ?? config.databaseUrl;
276	    migrationSummary = await ensureMigrations(migrationUrl, "PostgreSQL");
277	  
278	    db = createDb(config.databaseUrl);
279	    pluginMigrationDb = config.databaseMigrationUrl ? createDb(config.databaseMigrationUrl) : db;
280	    logger.info("Using external PostgreSQL via DATABASE_URL/config");
281	    activeDatabaseConnectionString = config.databaseUrl;
282	    startupDbInfo = { mode: "external-postgres", connectionString: config.databaseUrl };
283	  } else {
284	    const moduleName = "embedded-postgres";
285	    let EmbeddedPostgres: EmbeddedPostgresCtor;
286	    try {
287	      const mod = await import(moduleName);
288	      EmbeddedPostgres = mod.default as EmbeddedPostgresCtor;
289	    } catch {
290	      throw new Error(
291	        "Embedded PostgreSQL mode requires dependency `embedded-postgres`. Reinstall dependencies (without omitting required packages), or set DATABASE_URL for external Postgres.",
292	      );
293	    }
294	  
295	    const dataDir = resolve(config.embeddedPostgresDataDir);
296	    const configuredPort = config.embeddedPostgresPort;
297	    let port = configuredPort;
298	    const logBuffer = createEmbeddedPostgresLogBuffer(120);
299	    const verboseEmbeddedPostgresLogs = process.env.PAPERCLIP_EMBEDDED_POSTGRES_VERBOSE === "true";
300	    const appendEmbeddedPostgresLog = (message: unknown) => {
301	      logBuffer.append(message);
302	      if (!verboseEmbeddedPostgresLogs) {
303	        return;
304	      }
305	      const lines = typeof message === "string"
306	        ? message.split(/\r?\n/)
307	        : message instanceof Error
308	          ? [message.message]
309	          : [String(message ?? "")];
310	      for (const lineRaw of lines) {
311	        const line = lineRaw.trim();
312	        if (!line) continue;
313	        logger.info({ embeddedPostgresLog: line }, "embedded-postgres");
314	      }
315	    };
316	    const logEmbeddedPostgresFailure = (phase: "initialise" | "start", err: unknown) => {
317	      const recentLogs = logBuffer.getRecentLogs();
318	      if (recentLogs.length > 0) {
319	        logger.error(
320	          {
321	            phase,
322	            recentLogs,
323	            err,
324	          },
325	          "Embedded PostgreSQL failed; showing buffered startup logs",
326	        );
327	      }
328	    };
329	  
330	    if (config.databaseMode === "postgres") {
331	      logger.warn("Database mode is postgres but no connection string was set; falling back to embedded PostgreSQL");
332	    }
333	  
334	    const clusterVersionFile = resolve(dataDir, "PG_VERSION");
335	    const clusterAlreadyInitialized = existsSync(clusterVersionFile);
336	    const postmasterPidFile = resolve(dataDir, "postmaster.pid");
337	    const isPidRunning = (pid: number): boolean => {
338	      try {
339	        process.kill(pid, 0);
340	        return true;
341	      } catch {
342	        return false;
343	      }
344	    };
345	  
346	    const getRunningPid = (): number | null => {
347	      if (!existsSync(postmasterPidFile)) return null;
348	      try {
349	        const pidLine = readFileSync(postmasterPidFile, "utf8").split("\n")[0]?.trim();
350	        const pid = Number(pidLine);
351	        if (!Number.isInteger(pid) || pid <= 0) return null;
352	        if (!isPidRunning(pid)) return null;
353	        return pid;
354	      } catch {
355	        return null;
356	      }
357	    };
358	  
359	    const runningPid = getRunningPid();
360	    if (runningPid) {
361	      logger.warn(`Embedded PostgreSQL already running; reusing existing process (pid=${runningPid}, port=${port})`);
362	    } else {
363	      const configuredAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${configuredPort}/postgres`;
364	      try {
365	        const actualDataDir = await getPostgresDataDirectory(configuredAdminConnectionString);
366	        if (
367	          typeof actualDataDir !== "string" ||
368	          resolve(actualDataDir) !== resolve(dataDir)
369	        ) {
370	          throw new Error("reachable postgres does not use the expected embedded data directory");
371	        }
372	        await ensurePostgresDatabase(configuredAdminConnectionString, "paperclip");
373	        logger.warn(
374	          `Embedded PostgreSQL appears to already be reachable without a pid file; reusing existing server on configured port ${configuredPort}`,
375	        );
376	      } catch {
377	        const detectedPort = await detectPort(configuredPort);
378	        if (detectedPort !== configuredPort) {
379	          logger.warn(`Embedded PostgreSQL port is in use; using next free port (requestedPort=${configuredPort}, selectedPort=${detectedPort})`);
380	        }
381	        port = detectedPort;
382	        logger.info(`Using embedded PostgreSQL because no DATABASE_URL set (dataDir=${dataDir}, port=${port})`);
383	        embeddedPostgres = new EmbeddedPostgres({
384	          databaseDir: dataDir,
385	          user: "paperclip",
386	          password: "paperclip",
387	          port,
388	          persistent: true,
389	          initdbFlags: ["--encoding=UTF8", "--locale=C", "--lc-messages=C"],
390	          onLog: appendEmbeddedPostgresLog,
391	          onError: appendEmbeddedPostgresLog,
392	        });
393	
394	        if (!clusterAlreadyInitialized) {
395	          try {
396	            await embeddedPostgres.initialise();
397	          } catch (err) {
398	            logEmbeddedPostgresFailure("initialise", err);
399	            throw formatEmbeddedPostgresError(err, {
400	              fallbackMessage: `Failed to initialize embedded PostgreSQL cluster in ${dataDir} on port ${port}`,
401	              recentLogs: logBuffer.getRecentLogs(),
402	            });
403	          }
404	        } else {
405	          logger.info(`Embedded PostgreSQL cluster already exists (${clusterVersionFile}); skipping init`);
406	        }
407	
408	        if (existsSync(postmasterPidFile)) {
409	          logger.warn("Removing stale embedded PostgreSQL lock file");
410	          rmSync(postmasterPidFile, { force: true });
411	        }
412	        try {
413	          await embeddedPostgres.start();
414	        } catch (err) {
415	          logEmbeddedPostgresFailure("start", err);
416	          throw formatEmbeddedPostgresError(err, {
417	            fallbackMessage: `Failed to start embedded PostgreSQL on port ${port}`,
418	            recentLogs: logBuffer.getRecentLogs(),
419	          });
420	        }
421	        embeddedPostgresStartedByThisProcess = true;
422	      }
423	    }
424	  
425	    const embeddedAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/postgres`;
426	    const dbStatus = await ensurePostgresDatabase(embeddedAdminConnectionString, "paperclip");
427	    if (dbStatus === "created") {
428	      logger.info("Created embedded PostgreSQL database: paperclip");
429	    }
430	  
431	    const embeddedConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/paperclip`;
432	    const shouldAutoApplyFirstRunMigrations = !clusterAlreadyInitialized || dbStatus === "created";
433	    if (shouldAutoApplyFirstRunMigrations) {
434	      logger.info("Detected first-run embedded PostgreSQL setup; applying pending migrations automatically");
435	    }
436	    migrationSummary = await ensureMigrations(embeddedConnectionString, "Embedded PostgreSQL", {
437	      autoApply: shouldAutoApplyFirstRunMigrations,
438	    });
439	  
440	    db = createDb(embeddedConnectionString);
441	    pluginMigrationDb = db;
442	    logger.info("Embedded PostgreSQL ready");
443	    activeDatabaseConnectionString = embeddedConnectionString;
444	    resolvedEmbeddedPostgresPort = port;
445	    startupDbInfo = { mode: "embedded-postgres", dataDir, port };
446	  }
447	  
448	  if (config.deploymentMode === "local_trusted" && !isLoopbackHost(config.host)) {
449	    throw new Error(
450	      `local_trusted mode requires loopback host binding (received: ${config.host}). ` +
451	        "Use authenticated mode for non-loopback deployments.",
452	    );
453	  }
454	  
455	  if (config.deploymentMode === "local_trusted" && config.deploymentExposure !== "private") {
456	    throw new Error("local_trusted mode only supports private exposure");
457	  }
458	  
459	  if (config.deploymentMode === "authenticated") {
460	    if (config.authBaseUrlMode === "explicit" && !config.authPublicBaseUrl) {
461	      throw new Error("auth.baseUrlMode=explicit requires auth.publicBaseUrl");
462	    }
463	    if (config.deploymentExposure === "public") {
464	      if (config.authBaseUrlMode !== "explicit") {
465	        throw new Error("authenticated public exposure requires auth.baseUrlMode=explicit");
466	      }
467	      if (!config.authPublicBaseUrl) {
468	        throw new Error("authenticated public exposure requires auth.publicBaseUrl");
469	      }
470	    }
471	  }
472	
473	  const requestedListenPort = config.port;
474	  const listenPort = await detectPort(requestedListenPort);
475	  if (config.authBaseUrlMode === "explicit" && config.authPublicBaseUrl) {
476	    config.authPublicBaseUrl = rewriteLocalUrlPort(config.authPublicBaseUrl, listenPort);
477	  }
478	  
479	  let authReady = config.deploymentMode === "local_trusted";
480	  let betterAuthHandler: RequestHandler | undefined;
481	  let resolveSession:
482	    | ((req: ExpressRequest) => Promise<BetterAuthSessionResult | null>)
483	    | undefined;
484	  let resolveSessionFromHeaders:
485	    | ((headers: Headers) => Promise<BetterAuthSessionResult | null>)
486	    | undefined;
487	  if (config.deploymentMode === "local_trusted") {
488	    await ensureLocalTrustedBoardPrincipal(db as any);
489	  }
490	  if (config.deploymentMode === "authenticated") {
491	    const {
492	      createBetterAuthHandler,
493	      createBetterAuthInstance,
494	      deriveAuthTrustedOrigins,
495	      resolveBetterAuthSession,
496	      resolveBetterAuthSessionFromHeaders,
497	    } = await import("./auth/better-auth.js");
498	    const derivedTrustedOrigins = deriveAuthTrustedOrigins(config, { listenPort });
499	    const envTrustedOrigins = (process.env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
500	      .split(",")
501	      .map((value) => value.trim())
502	      .filter((value) => value.length > 0);
503	    const effectiveTrustedOrigins = Array.from(new Set([...derivedTrustedOrigins, ...envTrustedOrigins]));
504	    logger.info(
505	      {
506	        authBaseUrlMode: config.authBaseUrlMode,
507	        authPublicBaseUrl: config.authPublicBaseUrl ?? null,
508	        trustedOrigins: effectiveTrustedOrigins,
509	        trustedOriginsSource: {
510	          derived: derivedTrustedOrigins.length,
511	          env: envTrustedOrigins.length,
512	        },
513	      },
514	      "Authenticated mode auth origin configuration",
515	    );
516	    const auth = createBetterAuthInstance(db as any, config, effectiveTrustedOrigins);
517	    betterAuthHandler = createBetterAuthHandler(auth);
518	    resolveSession = (req) => resolveBetterAuthSession(auth, req);
519	    resolveSessionFromHeaders = (headers) => resolveBetterAuthSessionFromHeaders(auth, headers);
520	    await initializeBoardClaimChallenge(db as any, { deploymentMode: config.deploymentMode });
521	    authReady = true;
522	  }
523	
524	  if (resolvedEmbeddedPostgresPort !== null && resolvedEmbeddedPostgresPort !== config.embeddedPostgresPort) {
525	    config.embeddedPostgresPort = resolvedEmbeddedPostgresPort;
526	  }
527	  maybePersistWorktreeRuntimePorts({
528	    serverPort: listenPort,
529	    databasePort: resolvedEmbeddedPostgresPort,
530	  });
531	  const uiMode = config.uiDevMiddleware ? "vite-dev" : config.serveUi ? "static" : "none";
532	  const storageService = createStorageServiceFromConfig(config);
533	
534	  // Deployment platform awareness — log the configured platform at startup.
535	  // When deploymentPlatform is "cloudflare" the R2-backed run-log store,
536	  // workspace-operation-log store, and scheduler are managed inside the
537	  // Cloudflare Worker (packages/deploy-cloudflare). The Node server acts as a
538	  // sidecar for database access and scheduled work; all R2/Workers-only storage
539	  // paths are therefore NOT initialized here. Configuration of those bindings
540	  // belongs in the deploy-cloudflare Worker entry point.
541	  if (config.deploymentPlatform === "cloudflare") {
542	    logger.warn(
543	      { deploymentPlatform: config.deploymentPlatform },
544	      "Cloudflare platform mode is configured. The run-log store, workspace-operation-log store, " +
545	        "and scheduler are managed by the deploy-cloudflare Worker — this Node server is acting as " +
546	        "the sidecar. Ensure the deploy-cloudflare Worker is deployed and bound to the same database.",
547	    );
548	  }
549	
550	  const feedback = feedbackService(db as any, {
551	    shareClient: createFeedbackTraceShareClientFromConfig(config),
552	  });
553	  const backupSettingsSvc = instanceSettingsService(db);
554	  let databaseBackupInFlight = false;
555	  const runServerDatabaseBackup = async (
556	    trigger: InstanceDatabaseBackupTrigger,
557	  ): Promise<InstanceDatabaseBackupRunResult | null> => {
558	    if (databaseBackupInFlight) {
559	      const message = "Database backup already in progress";
560	      if (trigger === "scheduled") {
561	        logger.warn("Skipping scheduled database backup because a previous backup is still running");
562	        return null;
563	      }
564	      throw conflict(message);
